import React, { createContext, useState } from 'react';


export const PetContext = createContext();


export const PetProvider = ({ children }) => {

  const [petsData, setPetsData] = useState([
    { id: 1, location: 'Felix', description: 'A friendly cat', age: 2, price: 100, img: '/assets/road.jpg' },
    { id: 2, location: 'Bobik', description: 'A playful dog', age: 5, price: 300, img: '/assets/road.jpg' },
    { id: 3, location: 'Birdie', description: 'A singing bird', age: 1, price: 50, img: '/assets/road.jpg' },
    { id: 4, location: 'Djonii', description: 'A playful cat', age: 13, price: 150, img: '/assets/road.jpg' },
    { id: 5, location: 'Bibi', description: 'A special pet', age: 1, price: 325, img: '/assets/road.jpg' },
  ]);

  return (
    <PetContext.Provider value={{ petsData, setPetsData }}>
      {children}
    </PetContext.Provider>
  );
};
